create or replace function public.depurnrfi_d_register_artifact(p_artifact_id text,p_run_id text,p_artifact_type text,p_drive_file_id text,p_content_hash text,p_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare r record; begin select run_id into r from public.depurnrfi_d_runs where run_id=p_run_id; if not found then raise exception 'DEPURNRFI_D_RUN_NOT_FOUND'; end if; if coalesce(trim(p_artifact_id),'')='' or coalesce(trim(p_content_hash),'')='' then raise exception 'DEPURNRFI_D_ARTIFACT_ID_AND_HASH_REQUIRED'; end if; perform set_config('depurnrfi_d.kernel_commit','on',true); insert into public.depurnrfi_d_artifacts(artifact_id,run_id,artifact_type,drive_file_id,content_hash,readback_verified,metadata) values(p_artifact_id,p_run_id,p_artifact_type,p_drive_file_id,p_content_hash,false,coalesce(p_metadata,'{}'::jsonb)); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('artifact_id',p_artifact_id,'readback_verified',false); end $$;

create or replace function public.depurnrfi_d_mark_artifact_readback(p_artifact_id text,p_observed_hash text) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare a public.depurnrfi_d_artifacts%rowtype; begin select * into a from public.depurnrfi_d_artifacts where artifact_id=p_artifact_id for update; if not found then raise exception 'DEPURNRFI_D_ARTIFACT_NOT_FOUND'; end if; if a.content_hash<>p_observed_hash then raise exception 'DEPURNRFI_D_ARTIFACT_HASH_MISMATCH expected=% observed=%',a.content_hash,p_observed_hash; end if; perform set_config('depurnrfi_d.kernel_commit','on',true); update public.depurnrfi_d_artifacts set readback_verified=true,metadata=metadata||jsonb_build_object('readback_verified_at',clock_timestamp()) where artifact_id=p_artifact_id; perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('artifact_id',p_artifact_id,'readback_verified',true,'hash',p_observed_hash); end $$;

create or replace function public.depurnrfi_d_commit_pre_dialogue_report(p_run_id text,p_artifact_id text,p_report_sections jsonb) returns jsonb language plpgsql security definer set search_path=public,extensions as $$ declare r public.depurnrfi_d_runs%rowtype; a public.depurnrfi_d_artifacts%rowtype; c integer; payload text; h text; rid uuid; f11 text; new_ver integer; begin select * into r from public.depurnrfi_d_runs where run_id=p_run_id for update; if not found then raise exception 'DEPURNRFI_D_RUN_NOT_FOUND'; end if; if r.status<>'RUN_ACTIVE' or r.phase_cursor<>'REPORT_D' then raise exception 'DEPURNRFI_D_REPORT_NOT_READY status=% phase=%',r.status,r.phase_cursor; end if; select output_hash into f11 from public.depurnrfi_d_phase_receipts where run_id=p_run_id and phase_code='F11'; if f11 is null then raise exception 'DEPURNRFI_D_F11_RECEIPT_REQUIRED'; end if; if coalesce(trim(p_artifact_id),'')='' then raise exception 'DEPURNRFI_D_REPORT_ARTIFACT_REQUIRED'; end if; select * into a from public.depurnrfi_d_artifacts where artifact_id=p_artifact_id and run_id=p_run_id; if not found then raise exception 'DEPURNRFI_D_REPORT_ARTIFACT_NOT_REGISTERED'; end if; if a.artifact_type<>'FINAL_DEPURATION_REPORT_D' then raise exception 'DEPURNRFI_D_REPORT_ARTIFACT_TYPE_INVALID'; end if; if not a.readback_verified then raise exception 'DEPURNRFI_D_REPORT_DRIVE_READBACK_REQUIRED'; end if; if p_report_sections is null or jsonb_typeof(p_report_sections)<>'object' then raise exception 'DEPURNRFI_D_REPORT_OBJECT_REQUIRED'; end if; if coalesce(p_report_sections->>'report_type','')<>'FINAL_DEPURATION_REPORT_D' then raise exception 'DEPURNRFI_D_REPORT_TYPE_INVALID'; end if; begin c=(p_report_sections->>'candidate_count')::integer; exception when others then raise exception 'DEPURNRFI_D_REPORT_CANDIDATE_COUNT_REQUIRED'; end; if c<0 or c>4 then raise exception 'DEPURNRFI_D_REPORT_MAX_FOUR_VIOLATION'; end if; if jsonb_typeof(p_report_sections->'candidate_dossiers')<>'array' or jsonb_array_length(p_report_sections->'candidate_dossiers')<>c then raise exception 'DEPURNRFI_D_REPORT_CANDIDATE_DOSSIERS_MISMATCH'; end if; if not (p_report_sections ? 'exclusion_ledger' and p_report_sections ? 'd1_findings_summary' and p_report_sections ? 'd2_reconstruction_delta' and p_report_sections ? 'facts' and p_report_sections ? 'analyst_interpretation' and p_report_sections ? 'unresolved' and p_report_sections ? 'dialogue_topics' and p_report_sections ? 'chat_payload') then raise exception 'DEPURNRFI_D_REPORT_REQUIRED_SECTION_MISSING'; end if; payload=coalesce(p_report_sections->>'chat_payload',''); if length(trim(payload))<50 then raise exception 'DEPURNRFI_D_COMPLETE_CHAT_REPORT_REQUIRED'; end if; if public.depurnrfi_d_has_forbidden_key(p_report_sections,array['final_nrfi','final_nrfi_bet','bet','bet_size','probability','fair_price','edge','lock','rank_1_to_4']) then raise exception 'DEPURNRFI_D_REPORT_BETTING_AUTHORITY_FORBIDDEN'; end if; h=public.depurnrfi_d_jsonb_hash(p_report_sections); if a.content_hash<>h then raise exception 'DEPURNRFI_D_REPORT_ARTIFACT_CONTENT_HASH_MISMATCH'; end if; perform set_config('depurnrfi_d.kernel_commit','on',true); insert into public.depurnrfi_d_pre_dialogue_reports(run_id,artifact_id,report_type,candidate_count,report_sections,chat_payload,report_hash) values(p_run_id,p_artifact_id,'FINAL_DEPURATION_REPORT_D',c,p_report_sections,payload,h) returning report_id into rid; insert into public.depurnrfi_d_phase_receipts(run_id,phase_code,order_index,status,requirements_evaluated,output,output_hash) values(p_run_id,'REPORT_D',14,'COMMITTED',0,p_report_sections,h); new_ver=r.state_version+1; update public.depurnrfi_d_runs set status='WAITING_USER_AUTHORIZATION',phase_cursor='DIALOGUE',state_version=new_ver,pre_dialogue_frozen=true,report_id=rid,updated_at=clock_timestamp() where run_id=p_run_id; perform public.depurnrfi_d_append_event(p_run_id,'REPORT_D','PRE_DIALOGUE_REPORT_FROZEN',new_ver,jsonb_build_object('report_id',rid,'report_hash',h,'candidate_count',c,'artifact_id',p_artifact_id,'drive_readback',true,'next_state','STOP_WAITING_USER_AUTHORIZATION')); perform set_config('depurnrfi_d.kernel_commit','off',true); return jsonb_build_object('report_id',rid,'report_hash',h,'candidate_count',c,'artifact_id',p_artifact_id,'chat_payload',payload,'next_state','STOP_WAITING_USER_AUTHORIZATION','auto_continue',false); end $$;

revoke all on function public.depurnrfi_d_register_artifact(text,text,text,text,text,jsonb) from public,anon,authenticated; revoke all on function public.depurnrfi_d_mark_artifact_readback(text,text) from public,anon,authenticated; grant execute on function public.depurnrfi_d_register_artifact(text,text,text,text,text,jsonb) to service_role; grant execute on function public.depurnrfi_d_mark_artifact_readback(text,text) to service_role;
